<div class="card admin-card mb-4"><div class="card-header bg-white py-3 d-flex justify-content-between"><h2 class="h5 mb-0">4. Attractions</h2><button type="button" class="btn btn-sm btn-outline-success" data-repeater-add="attraction-rows" data-template="attraction-template">Add attraction</button></div><div class="card-body"><div id="attraction-rows" data-next-index="{{ $destination?->attractions->count() ?? 0 }}">@foreach($destination?->attractions ?? [] as $index => $attraction)<div class="border rounded p-3 mb-3" data-repeater-row><input type="hidden" name="attractions[{{ $index }}][id]" value="{{ $attraction->id }}"><div class="row g-3"><div class="col-md-4"><label class="form-label">Title</label><input class="form-control" name="attractions[{{ $index }}][title]" value="{{ $attraction->title }}"></div><div class="col-md-6"><label class="form-label">Description</label><textarea class="form-control" name="attractions[{{ $index }}][description]">{{ $attraction->description }}</textarea></div><div class="col-md-2"><label class="form-label">Order</label><input class="form-control" type="number" min="0" name="attractions[{{ $index }}][display_order]" value="{{ $attraction->display_order }}"></div><div class="col-md-10"><label class="form-label">Replace image</label><input class="form-control" type="file" name="attractions[{{ $index }}][image]" accept="image/jpeg,image/png,image/webp">@if($attraction->image_path)<img class="rounded mt-2" src="{{ Storage::disk('public')->url($attraction->image_path) }}" alt="" height="70">@endif</div><div class="col-md-2 form-check align-self-end mb-2"><input class="form-check-input" type="checkbox" name="attractions[{{ $index }}][_remove]" value="1" id="remove-attraction-{{ $attraction->id }}"><label class="form-check-label text-danger" for="remove-attraction-{{ $attraction->id }}">Remove</label></div></div></div>@endforeach</div></div></div>
<template id="attraction-template"><div class="border rounded p-3 mb-3" data-repeater-row><div class="row g-3"><div class="col-md-4"><label class="form-label">Title</label><input class="form-control" name="attractions[__INDEX__][title]" required></div><div class="col-md-6"><label class="form-label">Description</label><textarea class="form-control" name="attractions[__INDEX__][description]"></textarea></div><div class="col-md-2"><label class="form-label">Order</label><input class="form-control" type="number" min="0" name="attractions[__INDEX__][display_order]" value="0"></div><div class="col-md-10"><label class="form-label">Image</label><input class="form-control" type="file" name="attractions[__INDEX__][image]" accept="image/jpeg,image/png,image/webp"></div><div class="col-md-2 d-flex align-items-end"><button type="button" class="btn btn-outline-danger" data-remove-new-row>Remove</button></div></div></div></template>
